from scipy.optimize import least_squares
V=np.var(dv_dt)
def run(f,p0s):
    best=None
    for p0 in p0s:
        try:
            r=least_squares(lambda p: f(p)-dv_dt, p0, max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return np.mean((dv_dt-f(best.x))**2)/V, np.round(best.x,4)
